using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Measurements;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Temporal;
namespace Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Temporal;
internal abstract class TemporalRuleBase: AstronomyKnowledgeValidationRule<AstronomyTemporalPatternPayload>{protected static AstronomyKnowledgeValidationIssue Issue(string c,string m,string p,string r)=>new(c,AstronomyKnowledgeValidationSeverity.Error,m,p,r,AstronomyKnowledgeDomain.Temporal,AstronomyKnowledgePayloadFamily.TemporalCycle); public override AstronomyKnowledgeDomain Domain=>AstronomyKnowledgeDomain.Temporal; public override AstronomyKnowledgePayloadFamily Family=>AstronomyKnowledgePayloadFamily.TemporalCycle;}
public sealed class AstronomyTemporalPatternValidationRule:TemporalRuleBase{public const string Id="temporal.pattern.integrity"; public override string RuleId=>Id; public override int Order=>100; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyTemporalPatternPayload p,AstronomyKnowledgeValidationContext c){if(!Enum.IsDefined(p.Pattern.Kind)) yield return Issue(AstronomyTemporalValidationCodes.PatternKindInvalid,"Pattern kind must be defined.","$.pattern.kind",RuleId); if(c.Mode==AstronomyKnowledgeValidationMode.Strict&&(string.IsNullOrWhiteSpace(p.Pattern.Name)||string.IsNullOrWhiteSpace(p.Pattern.Summary))) yield return Issue(AstronomyTemporalValidationCodes.PatternTextIncomplete,"Strict temporal validation requires name and summary.","$.pattern",RuleId);}}
public sealed class AstronomyTemporalReferenceContextValidationRule:TemporalRuleBase{public const string Id="temporal.reference-context.compatibility"; public override string RuleId=>Id; public override int Order=>200; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyTemporalPatternPayload p,AstronomyKnowledgeValidationContext c){var r=p.Pattern.ReferenceContext; var ok=r.Basis switch{AstronomyTemporalReferenceBasis.Utc=>r.Entity is null&&r.Epoch is null&&r.ObservationContext is null, AstronomyTemporalReferenceBasis.EpochRelative=>r.Epoch is not null, AstronomyTemporalReferenceBasis.EntityRelative=>r.Entity is not null, AstronomyTemporalReferenceBasis.ObserverRelative=>r.ObservationContext is not null, _=>true}; if(!ok) yield return Issue(AstronomyTemporalValidationCodes.ReferenceContextIncompatible,"Temporal reference basis is incompatible with supplied context.","$.pattern.referenceContext",RuleId);}}
public sealed class AstronomyRecurrenceValidationRule:TemporalRuleBase{public const string Id="temporal.recurrence.matrix"; public override string RuleId=>Id; public override int Order=>300; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyTemporalPatternPayload p,AstronomyKnowledgeValidationContext c){var r=p.Pattern.Recurrence; if(!Enum.IsDefined(r.Kind)) yield return Issue(AstronomyTemporalValidationCodes.RecurrenceKindInvalid,"Recurrence kind must be defined.","$.pattern.recurrence.kind",RuleId); if((r.Kind==AstronomyRecurrenceKind.FixedPeriod)!=(r.FixedPeriod is not null)||(r.Kind==AstronomyRecurrenceKind.CalendarInterval)!=(r.CalendarInterval is not null)) yield return Issue(AstronomyTemporalValidationCodes.RecurrenceFieldsInvalid,"Recurrence fields must match recurrence kind.","$.pattern.recurrence",RuleId);}}
public sealed class AstronomyCyclePeriodValidationRule:TemporalRuleBase{public const string Id="temporal.cycle-period.dimension"; public override string RuleId=>Id; public override int Order=>400; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyTemporalPatternPayload p,AstronomyKnowledgeValidationContext c){var cp=p.Pattern.CyclePeriod; if(cp is null) yield break; if(cp.Duration.Unit.Dimension!=AstronomyMeasurementDimension.Time) yield return Issue(AstronomyTemporalValidationCodes.CyclePeriodDimensionInvalid,"Cycle period duration must use time dimension.","$.pattern.cyclePeriod.duration",RuleId); foreach(var i in AstronomyTemporalMeasurementValidator.Validate(cp.Duration,"$.pattern.cyclePeriod.duration",RuleId,Domain,Family)) yield return i; if(p.Pattern.Recurrence.Kind==AstronomyRecurrenceKind.CalendarInterval) yield return Issue(AstronomyTemporalValidationCodes.CyclePeriodRecurrenceMismatch,"Cycle period is not compatible with calendar-interval recurrence.","$.pattern.cyclePeriod",RuleId);}}
public sealed class AstronomyTemporalAnchorValidationRule:TemporalRuleBase{public const string Id="temporal.anchor.runtime"; public override string RuleId=>Id; public override int Order=>500; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyTemporalPatternPayload p,AstronomyKnowledgeValidationContext c){foreach(var i in Check(p.Pattern.Recurrence.Anchor,"$.pattern.recurrence.anchor")) yield return i;} IEnumerable<AstronomyKnowledgeValidationIssue> Check(AstronomyTemporalAnchor? a,string path){if(a is null) yield break; var ok=a switch{AstronomyUtcTemporalAnchor=>a.Kind==AstronomyTemporalAnchorKind.UtcInstant,AstronomyEpochTemporalAnchor=>a.Kind==AstronomyTemporalAnchorKind.Epoch,AstronomyCalendarDateTemporalAnchor=>a.Kind==AstronomyTemporalAnchorKind.CalendarDate,AstronomyDayOfYearTemporalAnchor=>a.Kind==AstronomyTemporalAnchorKind.DayOfYear,AstronomyMonthTemporalAnchor=>a.Kind==AstronomyTemporalAnchorKind.MonthOfYear,AstronomyCustomTemporalAnchor=>a.Kind==AstronomyTemporalAnchorKind.Custom,_=>false}; if(!ok) yield return Issue(AstronomyTemporalValidationCodes.AnchorKindMismatch,"Temporal anchor runtime type must match kind.",path+".kind",RuleId); if(a is AstronomyUtcTemporalAnchor u&&u.InstantUtc.Offset!=TimeSpan.Zero) yield return Issue(AstronomyTemporalValidationCodes.AnchorUtcInvalid,"UTC anchor instant must use UTC.",path+".instantUtc",RuleId);}}
public sealed class AstronomyTemporalPhaseValidationRule:TemporalRuleBase{public const string Id="temporal.phase.identity"; public override string RuleId=>Id; public override int Order=>600; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyTemporalPatternPayload p,AstronomyKnowledgeValidationContext c){if(p.Pattern.Phases.GroupBy(x=>x.PhaseId).Any(g=>g.Count()>1)) yield return Issue(AstronomyTemporalValidationCodes.PhaseDuplicate,"Phases must be unique by phase ID.","$.pattern.phases",RuleId); foreach(var ph in p.Pattern.Phases){ if(ph.Position is { } pos){foreach(var i in AstronomyTemporalMeasurementValidator.Validate(pos,"$.pattern.phases.position",RuleId,Domain,Family)) yield return i; if(pos.Unit.Dimension!=AstronomyMeasurementDimension.Dimensionless) yield return Issue(AstronomyTemporalValidationCodes.PhaseOffsetDimensionInvalid,"Phase position must be dimensionless.","$.pattern.phases.position",RuleId);} if(ph.Duration is { } d){foreach(var i in AstronomyTemporalMeasurementValidator.Validate(d,"$.pattern.phases.duration",RuleId,Domain,Family)) yield return i; if(d.Unit.Dimension!=AstronomyMeasurementDimension.Time) yield return Issue(AstronomyTemporalValidationCodes.PhaseDurationDimensionInvalid,"Phase duration must use time dimension.","$.pattern.phases.duration",RuleId);}}}}
public sealed class AstronomyTemporalOccurrenceValidationRule:TemporalRuleBase{public const string Id="temporal.occurrence.identity"; public override string RuleId=>Id; public override int Order=>700; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyTemporalPatternPayload p,AstronomyKnowledgeValidationContext c){var o=p.Pattern.SuppliedOccurrences; if(o.GroupBy(x=>(x.StartUtc,x.EndUtc,x.PhaseId)).Any(g=>g.Count()>1)) yield return Issue(AstronomyTemporalValidationCodes.OccurrenceDuplicate,"Occurrences must be unique by start, end, and phase ID.","$.pattern.suppliedOccurrences",RuleId); var phases=p.Pattern.Phases.Select(x=>x.PhaseId).ToHashSet(); foreach(var x in o){if(x.StartUtc.Offset!=TimeSpan.Zero||x.EndUtc?.Offset!=TimeSpan.Zero) yield return Issue(AstronomyTemporalValidationCodes.OccurrenceUtcInvalid,"Occurrence times must use UTC.","$.pattern.suppliedOccurrences",RuleId); if(x.EndUtc<x.StartUtc) yield return Issue(AstronomyTemporalValidationCodes.OccurrenceOrderingInvalid,"Occurrence end cannot precede start.","$.pattern.suppliedOccurrences",RuleId); if(x.PhaseId is { } id&&!phases.Contains(id)) yield return Issue(AstronomyTemporalValidationCodes.OccurrencePhaseMissing,"Occurrence phase reference must exist.","$.pattern.suppliedOccurrences.phaseId",RuleId);}}}
public sealed class AstronomySeasonalPatternValidationRule:TemporalRuleBase{public const string Id="temporal.seasonal.policy"; public override string RuleId=>Id; public override int Order=>800; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyTemporalPatternPayload p,AstronomyKnowledgeValidationContext c){var s=p.Pattern.Season; if(s is null) yield break; var start=s.Start.Month*100+s.Start.Day; var end=s.End.Month*100+s.End.Day; if(!s.CrossesYearBoundary&&start>end) yield return Issue(AstronomyTemporalValidationCodes.SeasonalOrderingInvalid,"Non-wrapping seasonal pattern start cannot be after end.","$.pattern.season",RuleId); if(s.CrossesYearBoundary&&start<=end) yield return Issue(AstronomyTemporalValidationCodes.SeasonalOrderingInvalid,"Wrapping seasonal pattern must cross the year boundary.","$.pattern.season",RuleId);}}
public sealed class AstronomyTemporalApplicabilityValidationRule:TemporalRuleBase{public const string Id="temporal.applicability.extent"; public override string RuleId=>Id; public override int Order=>900; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyTemporalPatternPayload p,AstronomyKnowledgeValidationContext c){var a=p.Pattern.Applicability; if(a is null) yield break; if(a.FromUtc?.Offset!=TimeSpan.Zero||a.ThroughUtc?.Offset!=TimeSpan.Zero) yield return Issue(AstronomyTemporalValidationCodes.ApplicabilityUtcInvalid,"Applicability instants must use UTC.","$.pattern.applicability",RuleId); if(a.ThroughUtc<a.FromUtc) yield return Issue(AstronomyTemporalValidationCodes.ApplicabilityOrderingInvalid,"Applicability end cannot precede start.","$.pattern.applicability",RuleId);}}
